d5_registry.source:
def d5_active():
    """U8 owns activation. There is no runtime override."""
    return d5_activation.d5_active()

def _require(condition, message):
    if not condition:
        raise AuthorityError("registry: " + message)

def _active():
    _require(d5_active(), "D5 is not active")

def register(checkout, plan_id, state_dir):
    """Register one (repo object, plan) with one state object, or return it intact."""
    _active()
    return _register(checkout, plan_id, state_dir)

d5_lease.source:
def _active():
    if not d5_registry.d5_active():
        raise d5_registry.AuthorityError("D5 is not active")

def grant(checkout, plan_id, state_dir, *, issued_at, confirmed_at, expires_at,
          mandate_bytes, scope, owner_response, displayed_bounds):
    """Create or replace a validated grant with exact owner confirmation."""
    _active()
    record = {"schema_version": 1, "grant_id": uuid.uuid4().hex,
              "issued_at": issued_at, "confirmed_at": confirmed_at,
              "expires_at": expires_at, "session_cap": 1,
              "mandate_sha256": authority.mandate_digest(mandate_bytes),
              "scope": scope, "confirmation": {"owner_response": owner_response,
                                               "displayed_bounds": displayed_bounds},
              "custody": None, "invalidation": None}
    authority.validate(record)
    entry = _registered(checkout, plan_id, state_dir)
    directory = Path(entry["record_dir"])
    operation = (d5_install.replace_authority
                 if store.present(directory / store.RECORD_NAME, "record")
                 else d5_install.install_initial)
    with _grant_locked(directory):
        return operation(directory, record)

d5_custody.source:
def _active():
    if not d5_registry.d5_active():
        raise authority.AuthorityError("D5 is not active")

def claim(checkout, plan_id, state_dir, *, now, mandate_bytes):
    """Delegate to R3 using the freshly resolved registration's mandate source.

    now and mandate_bytes remain for signature compatibility; the active branch
    does not use them. R3 samples time, native identity and registered bytes
    under its locks. Its store.read_bytes opens with O_NOFOLLOW and refuses
    a non-regular mandate file.
    """
    _active()
    entry = d5_registry.lookup(checkout, plan_id, state_dir)
    if entry is None:
        raise authority.AuthorityError("not registered")
    return d5_install.claim_custody(entry["record_dir"], mandate_path=(
        Path(entry["checkout"]) / "docs/orchestrator-mandate.md"))
